import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const TRANSITION = 20;

// Each logo scene duration
const LOGO_DURATION = 100;
// Total: 4 logos + transitions + black bookends
// Sequences: 20 + (100+20)*4 + 25 = 20 + 480 + 25 = 525
// Transitions: 20 (open) + 20*4 (between logos + close) = 100
// durationInFrames = 20 + 480 + 25 - (20 + 20*3 + 20) = 525 - 100 = 425
// Let me recalculate carefully:
// Sequences: Black(20) + Logo1(120) + Logo2(120) + Logo3(120) + Logo4(120) + Black(25) = 525
// Transitions: fade(20) + fade(20) + fade(20) + fade(20) + fade(20) = 100
// Total = 525 - 100 = 425

export const durationInFrames = 425;

const COLORS = {
  bg: "#000000",
  white: "#FFFFFF",
  cursorBlue: "#1B6FF8",
  cursorDark: "#0D0D0D",
  claudeOrange: "#D97757",
  claudePeach: "#F5E6D8",
  googleBlue: "#4285F4",
  googleRed: "#EA4335",
  googleYellow: "#FBBC05",
  googleGreen: "#34A853",
  openaiGray: "#10a37f",
  openaiDark: "#1a1a2e",
};

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─────────────────────────────────────────────
// CURSOR AI LOGO
// ─────────────────────────────────────────────
const CursorLogo: React.FC<{ progress: number }> = ({ progress }) => {
  const opacity = progress;
  const scale = interpolate(progress, [0, 1], [0.85, 1]);
  const translateY = interpolate(progress, [0, 1], [80, 0]);

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale}) translateY(${translateY}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 60,
      }}
    >
      {/* Cursor icon - the iconic cursor + box */}
      <svg width="320" height="320" viewBox="0 0 100 100" fill="none">
        {/* Dark background square */}
        <rect width="100" height="100" rx="22" fill="#000000" />

        {/* White cursor arrow */}
        <path
          d="M28 20 L28 68 L40 56 L50 78 L58 74 L48 52 L64 52 Z"
          fill="white"
          opacity={opacity}
        />
        {/* Cursor blink line */}
        <line
          x1="66"
          y1="58"
          x2="66"
          y2="78"
          stroke="white"
          strokeWidth="5"
          strokeLinecap="round"
          opacity={interpolate(progress, [0.5, 1], [0, 1])}
        />
      </svg>

      {/* Wordmark */}
      <div
        style={{
          color: "#FFFFFF",
          fontSize: 96,
          fontWeight: 700,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "-2px",
          opacity: interpolate(progress, [0.3, 1], [0, 1]),
        }}
      >
        Cursor
      </div>

      {/* Tagline */}
      <div
        style={{
          color: "rgba(255,255,255,0.5)",
          fontSize: 42,
          fontWeight: 400,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "0.1em",
          opacity: interpolate(progress, [0.5, 1], [0, 1]),
        }}
      >
        The AI Code Editor
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// CLAUDE LOGO
// ─────────────────────────────────────────────
const ClaudeLogo: React.FC<{ progress: number }> = ({ progress }) => {
  const opacity = progress;
  const scale = interpolate(progress, [0, 1], [0.85, 1]);
  const translateY = interpolate(progress, [0, 1], [80, 0]);

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale}) translateY(${translateY}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 60,
      }}
    >
      {/* Claude icon - Anthropic's diamond/asterisk mark */}
      <svg width="320" height="320" viewBox="0 0 200 200" fill="none">
        {/* Anthropic-style starburst / asterisk */}
        {[0, 30, 60, 90, 120, 150].map((angle, i) => {
          const rad = (angle * Math.PI) / 180;
          const x1 = 100 + 15 * Math.cos(rad);
          const y1 = 100 + 15 * Math.sin(rad);
          const x2 = 100 + 85 * Math.cos(rad);
          const y2 = 100 + 85 * Math.sin(rad);
          const x3 = 100 + 15 * Math.cos(rad + Math.PI);
          const y3 = 100 + 15 * Math.sin(rad + Math.PI);
          const x4 = 100 + 85 * Math.cos(rad + Math.PI);
          const y4 = 100 + 85 * Math.sin(rad + Math.PI);
          const lineProgress = interpolate(progress, [i * 0.05, i * 0.05 + 0.5], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <line
              key={angle}
              x1={x1}
              y1={y1}
              x2={interpolate(lineProgress, [0, 1], [x1, x2])}
              y2={interpolate(lineProgress, [0, 1], [y1, y2])}
              stroke={COLORS.claudeOrange}
              strokeWidth="14"
              strokeLinecap="round"
              opacity={lineProgress}
            />
          );
        })}
        {[0, 30, 60, 90, 120, 150].map((angle, i) => {
          const rad = (angle * Math.PI) / 180;
          const x3 = 100 + 15 * Math.cos(rad + Math.PI);
          const y3 = 100 + 15 * Math.sin(rad + Math.PI);
          const x4 = 100 + 85 * Math.cos(rad + Math.PI);
          const y4 = 100 + 85 * Math.sin(rad + Math.PI);
          const lineProgress = interpolate(progress, [i * 0.05, i * 0.05 + 0.5], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          return (
            <line
              key={`b${angle}`}
              x1={x3}
              y1={y3}
              x2={interpolate(lineProgress, [0, 1], [x3, x4])}
              y2={interpolate(lineProgress, [0, 1], [y3, y4])}
              stroke={COLORS.claudeOrange}
              strokeWidth="14"
              strokeLinecap="round"
              opacity={lineProgress}
            />
          );
        })}
      </svg>

      {/* Wordmark */}
      <div
        style={{
          color: COLORS.claudeOrange,
          fontSize: 96,
          fontWeight: 700,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "-2px",
          opacity: interpolate(progress, [0.3, 1], [0, 1]),
        }}
      >
        Claude
      </div>

      <div
        style={{
          color: "rgba(255,255,255,0.5)",
          fontSize: 42,
          fontWeight: 400,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "0.1em",
          opacity: interpolate(progress, [0.5, 1], [0, 1]),
        }}
      >
        by Anthropic
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// GOOGLE ANTIGRAVITY LOGO  
// ─────────────────────────────────────────────
const GoogleAntigravityLogo: React.FC<{ progress: number }> = ({ progress }) => {
  const opacity = progress;
  const scale = interpolate(progress, [0, 1], [0.85, 1]);
  const translateY = interpolate(progress, [0, 1], [80, 0]);

  // Floating/antigravity effect on the G
  const floatY = interpolate(progress, [0.7, 1], [0, -20]);
  const orbitProgress = interpolate(progress, [0.5, 1], [0, 1]);

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale}) translateY(${translateY}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 60,
      }}
    >
      {/* Google G with antigravity orbit ring */}
      <div style={{ position: "relative", width: 320, height: 320 }}>
        <svg width="320" height="320" viewBox="0 0 200 200" fill="none">
          {/* Orbit ring */}
          <ellipse
            cx="100"
            cy="100"
            rx="90"
            ry="28"
            stroke="rgba(255,255,255,0.2)"
            strokeWidth="2"
            fill="none"
            strokeDasharray="8 6"
            transform={`rotate(${interpolate(orbitProgress, [0, 1], [-15, 0])}deg)`}
          />

          {/* Orbiting dot */}
          {[0, 1, 2].map((i) => {
            const angle = interpolate(orbitProgress, [0, 1], [180 + i * 120, 360 + i * 120]);
            const rad = (angle * Math.PI) / 180;
            const cx = 100 + 90 * Math.cos(rad);
            const cy = 100 + 28 * Math.sin(rad);
            const colors = [COLORS.googleBlue, COLORS.googleRed, COLORS.googleYellow];
            return (
              <circle
                key={i}
                cx={cx}
                cy={cy}
                r={6}
                fill={colors[i]}
                opacity={interpolate(orbitProgress, [0, 0.3], [0, 1], {
                  extrapolateRight: "clamp",
                })}
              />
            );
          })}

          {/* The Google G */}
          <g transform={`translate(100, ${100 + floatY}) scale(0.72)`} style={{ transformOrigin: "0 0" }}>
            {/* G shape built from arcs and a rect */}
            {/* Outer arc - colored segments */}
            <path
              d="M 0,-85 A 85,85 0 0,1 85,0"
              stroke={COLORS.googleBlue}
              strokeWidth="24"
              fill="none"
              strokeLinecap="round"
              opacity={interpolate(progress, [0.1, 0.5], [0, 1], { extrapolateRight: "clamp" })}
            />
            <path
              d="M 85,0 A 85,85 0 0,1 0,85"
              stroke={COLORS.googleRed}
              strokeWidth="24"
              fill="none"
              strokeLinecap="round"
              opacity={interpolate(progress, [0.2, 0.6], [0, 1], { extrapolateRight: "clamp" })}
            />
            <path
              d="M 0,85 A 85,85 0 0,1 -85,0"
              stroke={COLORS.googleYellow}
              strokeWidth="24"
              fill="none"
              strokeLinecap="round"
              opacity={interpolate(progress, [0.3, 0.7], [0, 1], { extrapolateRight: "clamp" })}
            />
            <path
              d="M -85,0 A 85,85 0 0,1 0,-85"
              stroke={COLORS.googleGreen}
              strokeWidth="24"
              fill="none"
              strokeLinecap="round"
              opacity={interpolate(progress, [0.4, 0.8], [0, 1], { extrapolateRight: "clamp" })}
            />
            {/* Horizontal bar for G */}
            <rect
              x="0"
              y="-14"
              width={interpolate(orbitProgress, [0, 1], [0, 85])}
              height="28"
              fill={COLORS.googleBlue}
              rx="4"
              opacity={interpolate(progress, [0.5, 0.9], [0, 1], { extrapolateRight: "clamp" })}
            />
          </g>
        </svg>
      </div>

      {/* Wordmark */}
      <div
        style={{
          display: "flex",
          gap: 4,
          fontSize: 96,
          fontWeight: 700,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "-2px",
          opacity: interpolate(progress, [0.3, 1], [0, 1]),
        }}
      >
        {["G", "o", "o", "g", "l", "e"].map((letter, i) => {
          const letterColors = [
            COLORS.googleBlue,
            COLORS.googleRed,
            COLORS.googleYellow,
            COLORS.googleBlue,
            COLORS.googleGreen,
            COLORS.googleRed,
          ];
          return (
            <span key={i} style={{ color: letterColors[i] }}>
              {letter}
            </span>
          );
        })}
      </div>

      <div
        style={{
          color: "rgba(255,255,255,0.5)",
          fontSize: 42,
          fontWeight: 400,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "0.05em",
          opacity: interpolate(progress, [0.5, 1], [0, 1]),
        }}
      >
        Antigravity
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// OPENAI CODEX LOGO
// ─────────────────────────────────────────────
const OpenAICodexLogo: React.FC<{ progress: number }> = ({ progress }) => {
  const opacity = progress;
  const scale = interpolate(progress, [0, 1], [0.85, 1]);
  const translateY = interpolate(progress, [0, 1], [80, 0]);

  const spinProgress = interpolate(progress, [0.4, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        opacity,
        transform: `scale(${scale}) translateY(${translateY}px)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 60,
      }}
    >
      {/* OpenAI bloom / swirl */}
      <svg width="320" height="320" viewBox="0 0 200 200" fill="none">
        {/* Outer glow ring */}
        <circle
          cx="100"
          cy="100"
          r="88"
          stroke={COLORS.openaiGray}
          strokeWidth="2"
          fill="none"
          opacity={interpolate(progress, [0, 0.4], [0, 0.3])}
        />

        {/* OpenAI-style overlapping petal shapes */}
        {Array.from({ length: 8 }).map((_, i) => {
          const angle = (i * 45 * Math.PI) / 180;
          const petalProgress = interpolate(
            progress,
            [i * 0.04, i * 0.04 + 0.45],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const cx1 = 100 + 38 * Math.cos(angle);
          const cy1 = 100 + 38 * Math.sin(angle);
          return (
            <ellipse
              key={i}
              cx={cx1}
              cy={cy1}
              rx={interpolate(petalProgress, [0, 1], [0, 38])}
              ry={interpolate(petalProgress, [0, 1], [0, 14])}
              fill="none"
              stroke={COLORS.openaiGray}
              strokeWidth="3.5"
              opacity={interpolate(petalProgress, [0, 0.3], [0, 0.85])}
              transform={`rotate(${(angle * 180) / Math.PI + interpolate(spinProgress, [0, 1], [0, 45])}, ${cx1}, ${cy1})`}
            />
          );
        })}

        {/* Center dot */}
        <circle
          cx="100"
          cy="100"
          r={interpolate(progress, [0.4, 0.8], [0, 14])}
          fill={COLORS.openaiGray}
          opacity={interpolate(progress, [0.4, 0.8], [0, 1])}
        />
      </svg>

      {/* Wordmark */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 8,
          opacity: interpolate(progress, [0.3, 1], [0, 1]),
        }}
      >
        <div
          style={{
            color: "#FFFFFF",
            fontSize: 96,
            fontWeight: 700,
            fontFamily: "'Inter', sans-serif",
            letterSpacing: "-2px",
          }}
        >
          OpenAI
        </div>
        <div
          style={{
            color: COLORS.openaiGray,
            fontSize: 56,
            fontWeight: 600,
            fontFamily: "'Inter', sans-serif",
            letterSpacing: "0.15em",
            opacity: interpolate(progress, [0.5, 1], [0, 1]),
          }}
        >
          CODEX
        </div>
      </div>

      <div
        style={{
          color: "rgba(255,255,255,0.5)",
          fontSize: 42,
          fontWeight: 400,
          fontFamily: "'Inter', sans-serif",
          letterSpacing: "0.1em",
          opacity: interpolate(progress, [0.5, 1], [0, 1]),
        }}
      >
        AI for Code
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────
// SCENE WRAPPERS
// ─────────────────────────────────────────────

const SceneCursor: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'Inter', sans-serif",
      }}
    >
      <CursorLogo progress={progress} />
    </AbsoluteFill>
  );
};

const SceneClaude: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'Inter', sans-serif",
