// ─────────────────────────────────────────────
// MAIN COMPOSITION
// ─────────────────────────────────────────────

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 1 - Cursor */}
      <TransitionSeries.Sequence durationInFrames={LOGO_DURATION + TRANSITION}>
        <SceneCursor />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 2 - Claude */}
      <TransitionSeries.Sequence durationInFrames={LOGO_DURATION + TRANSITION}>
        <SceneClaude />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 3 - Google Antigravity */}
      <TransitionSeries.Sequence durationInFrames={LOGO_DURATION + TRANSITION}>
        <SceneGoogleAntigravity />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 4 - OpenAI Codex */}
      <TransitionSeries.Sequence durationInFrames={LOGO_DURATION + TRANSITION}>
        <SceneOpenAICodex />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
